contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 value) public {
        require(to != address(0));
        require(value <= c.balanceOf(address(this)));

        uint256 totalBefore = c.totalSupply();
        uint256 fromBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 fromAfter = c.balanceOf(address(this));
        uint256 toAfter = c.balanceOf(to);

        assert(
            reverted
            ? (fromAfter == fromBefore && toAfter == toBefore && totalAfter == totalBefore)
            : (fromAfter == fromBefore - value && toAfter == toBefore + value && totalAfter == totalBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 burnAmount) public payable {
        require(burnAmount > 0);

        address ownerAddr = c.owner();
        uint256 balanceBefore = c.balanceOf(ownerAddr);
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 balanceAfter = c.balanceOf(ownerAddr);
            uint256 supplyAfter = c.totalSupply();
            assert(balanceAfter == balanceBefore - burnAmount && supplyAfter == supplyBefore - burnAmount);
        } else {
            assert(burnAmount > balanceBefore);
        }
    }

    receive() external payable {}
}

