contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 value) public payable {
        require(to != address(0));
        uint256 beforeOwnerBalance = c.balanceOf(msg.sender);
        uint256 beforeToBalance = c.balanceOf(to);
        uint256 beforeTotalSupply = c.totalSupply();
        require(beforeOwnerBalance >= value);
        require(!c.frozenAccount(msg.sender));
        require(!c.frozenAccount(to));

        c.transfer(to, value);

        assert(
            c.balanceOf(msg.sender) + value == beforeOwnerBalance &&
            c.balanceOf(to) == beforeToBalance + value &&
            c.balanceOf(msg.sender) + c.balanceOf(to) + (beforeTotalSupply - beforeOwnerBalance - beforeToBalance) == c.totalSupply()
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 freezeAmount) public payable {
        require(freezeAmount > 0);
        require(target != address(0));
        require(target != address(this));

        c.mintToken(target, freezeAmount);

        uint256 targetBefore = c.balanceOf(target);
        uint256 recipientBefore = c.balanceOf(msg.sender);

        c.freezeAccount(target, true);

        bool frozenState = c.frozenAccount(target);
        require(frozenState);

        bool reverted;
        try c.transfer(msg.sender, 1) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 targetAfter = c.balanceOf(target);
        uint256 recipientAfter = c.balanceOf(msg.sender);

        assert(reverted && targetAfter == targetBefore && recipientAfter == recipientBefore);
    }

    receive() external payable {}
}

